#!/usr/bin/env python3
"""Render a Markdown behavior-testing summary from the Cucumber JSON report.

Reads ``**/target/cucumber-reports/cucumber.json`` (generated by the Cucumber
``json`` plugin) and prints per-feature scenario counts, failures and duration.
"""

from __future__ import annotations

import glob
import json
import os
import sys

REPORT_GLOB = os.environ.get("CUCUMBER_REPORT_GLOB", "**/target/cucumber-reports/cucumber.json")
STATUSES = ("passed", "failed", "skipped", "undefined", "pending", "ambiguous")
FAILED = {"failed", "undefined", "ambiguous"}

def feature_name(feature: dict) -> str:
  """Return a readable feature label."""
  name = (feature.get("name") or "").strip() or os.path.basename(feature.get("uri", "feature"))
  return name

def scenario_status(scenario: dict) -> str:
  """Reduce a scenario to its worst step status."""
  statuses = [(step.get("result") or {}).get("status", "skipped") for step in scenario.get("steps", [])]
  for status in FAILED:
    if status in statuses:
      return status
  return "skipped" if statuses and all(s == "skipped" for s in statuses) else "passed"

def scenario_duration(scenario: dict) -> int:
  """Sum the step durations of a scenario, in nanoseconds."""
  return sum((step.get("result") or {}).get("duration") or 0 for step in scenario.get("steps", []))

def find_reports() -> list[str]:
  """Return every Cucumber JSON report found in the workspace."""
  return sorted(glob.glob(REPORT_GLOB, recursive=True))

def render(reports: list[str]) -> str:
  """Build the Markdown document."""
  lines = ["## 🧪 Behaviour Testing Report", ""]

  if not reports:
    lines.extend([
      "### ⚠️ No Cucumber reports were generated",
      "",
      "The runner did not produce `cucumber.json`. Review the *Run Behaviour Tests* step."])
    return "\n".join(lines) + "\n"

  totals = dict.fromkeys(STATUSES, 0)
  failures: list[str] = []
  rows: list[str] = []
  duration = 0

  for report in reports:
    try:
      features = json.load(open(report, encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
      lines.extend([
        f"### ⚠️ Could not read `{report}`",
        "",
        f"```\n{error}\n```"])
      return "\n".join(lines) + "\n"

    for feature in features:
      counts = dict.fromkeys(STATUSES, 0)
      for element in feature.get("elements", []):
        if element.get("type") != "scenario":
          continue
        status = scenario_status(element)
        counts[status] += 1
        duration += scenario_duration(element)
        if status in FAILED:
          failures.append(f"`{scenario_name(feature, element)}` — {status}")

      scenarios = sum(counts.values())
      if not scenarios:
        continue
      for status, value in counts.items():
        totals[status] += value
      rows.append(
        f"| {feature_name(feature)} | {scenarios} | {counts['passed']} | "
        f"{counts['failed']} | {scenarios - counts['passed'] - counts['failed']} |"
      )

  if not rows:
    lines.append("### ⚠️ No scenarios were executed")
    return "\n".join(lines) + "\n"

  scenarios = sum(totals.values())
  lines.extend([
    "| Feature | Scenarios | Passed | Failed | Skipped |",
    "|---|---:|---:|---:|---:|"])
  lines.extend(rows)
  lines.extend([
    f"| **Total** | **{scenarios}** | **{totals['passed']}** | **{totals['failed']}** | "
    f"**{scenarios - totals['passed'] - totals['failed']}** |",
    "",
    f"⏱️ Duration: {duration / 1_000_000_000:.1f}s",
    ""])

  if failures:
    lines.append("### ❌ Failed scenarios")
    lines.append("")
    lines.extend(f"- {failure}" for failure in failures[:20])
    if len(failures) > 20:
      lines.append(f"- … y {len(failures) - 20} más")

  return "\n".join(lines) + "\n"

def scenario_name(feature: dict, scenario: dict) -> str:
  """Compose a `Feature: Scenario` label for the failure list."""
  return f"{(feature.get('name') or '').strip()}: {(scenario.get('name') or '').strip()}"

def main() -> int:
  """Print the summary to stdout so the caller can tee it to the job summary."""
  sys.stdout.write(render(find_reports()))
  return 0

if __name__ == "__main__":
  sys.exit(main())
